[metadata] {"type": "create", "filePath": "/workspace/repo/mlflow/bedrock/genai_semconv_converter.py", "content": """"
Bedrock Converse-format message converter for GenAI Semantic Convention export.

Translates the Bedrock Converse API request/response structures into the OpenTelemetry
GenAI semantic convention attributes: gen_ai.input.messages, gen_ai.output.messages,
gen_ai.system_instructions, request params, and tool definitions.

Ref: https://docs.aws.amazon.com/bedrock/latest/APIReference/API_runtime_Converse.html
"""

import base64
import json
from typing import Any

from mlflow.tracing.constant import GenAiSemconvKey
from mlflow.tracing.export.genai_semconv.converter import GenAiSemconvConverter


class BedrockConverseConverter(GenAiSemconvConverter):
    def convert_inputs(self, inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        messages = inputs.get("messages")
        if not isinstance(messages, list):
            return None
        return [_convert_message(m) for m in messages]

    def convert_system_instructions(self, inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        system = inputs.get("system")
        if not isinstance(system, list):
            return None
        parts = []
        for block in system:
            if isinstance(block, dict) and (text := block.get("text")) is not None:
                parts.append({"type": "text", "content": text})
        return parts or None

    def convert_outputs(self, outputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        output = outputs.get("output")
        if not isinstance(output, dict):
            return None
        message = output.get("message")
        if not isinstance(message, dict):
            return None
        return [_convert_message(message)]

    def extract_request_params(self, inputs: dict[str, Any]) -> dict[str, Any]:
        params: dict[str, Any] = {}
        config = inputs.get("inferenceConfig")
        if isinstance(config, dict):
            if (temperature := config.get("temperature")) is not None:
                params[GenAiSemconvKey.REQUEST_TEMPERATURE] = temperature
            if (max_tokens := config.get("maxTokens")) is not None:
                params[GenAiSemconvKey.REQUEST_MAX_TOKENS] = max_tokens
            if (top_p := config.get("topP")) is not None:
                params[GenAiSemconvKey.REQUEST_TOP_P] = top_p
            if (stop_sequences := config.get("stopSequences")) is not None:
                params[GenAiSemconvKey.REQUEST_STOP_SEQUENCES] = stop_sequences

        tool_config = inputs.get("toolConfig")
        if isinstance(tool_config, dict) and isinstance(tool_config.get("tools"), list):
            params[GenAiSemconvKey.TOOL_DEFINITIONS] = _convert_tools(tool_config["tools"])

        return params


def _convert_message(msg: dict[str, Any]) -> dict[str, Any]:
    role = msg.get("role", "user")
    content = msg.get("content")
    if not isinstance(content, list):
        return {"role": role, "parts": []}

    parts = []
    has_tool_result = False
    for block in content:
        converted = _convert_block(block)
        parts.append(converted)
        if converted.get("type") == "tool_call_response":
            has_tool_result = True

    # Bedrock sends tool results inside a "user" role message. Override it to "tool".
    if has_tool_result:
        return {"role": "tool", "parts": parts}
    return {"role": role, "parts": parts}


def _convert_block(block: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(block, dict):
        return {"type": "text", "content": json.dumps(block)}

    if (text := block.get("text")) is not None:
        return {"type": "text", "content": text}
    if (image := block.get("image")) is not None:
        return _convert_image(image)
    if (tool_use := block.get("toolUse")) is not None:
        return {
            "type": "tool_call",
            "id": tool_use.get("toolUseId", ""),
            "name": tool_use.get("name", ""),
            "arguments": tool_use.get("input"),
        }
    if (tool_result := block.get("toolResult")) is not None:
        return {
            "type": "tool_call_response",
            "id": tool_result.get("toolUseId", ""),
            "result": json.dumps(tool_result.get("content", [])),
        }
    return {"type": "text", "content": json.dumps(block)}


def _convert_image(image: dict) -> dict:
    fmt = image.get("format", "")
    source = image.get("source", {})
    data = source.get("bytes", "")
    content = base64.b64encode(data).decode("utf-8") if isinstance(data, bytes) else data
    return {
        "type": "blob",
        "modality": "image",
        "mime_type": f"image/{fmt}",
        "content": content,
    }


def _convert_tools(tools: list[dict[str, Any]]) -> str:
    converted = []
    for tool in tools:
        spec = tool.get("toolSpec", {}) if isinstance(tool, dict) else {}
        definition: dict[str, Any] = {"name": spec.get("name", "")}
        if (description := spec.get("description")) is not None:
            definition["description"] = description
        input_schema = spec.get("inputSchema", {})
        if isinstance(input_schema, dict) and "json" in input_schema:
            definition["parameters"] = input_schema["json"]
        converted.append(definition)
    return json.dumps(converted)
